#include <bits/stdc++.h>
using namespace std;
#define int long long
int32_t main() {
	// your code goes here
	int t;
	cin>>t;
	while(t--){
	    int n;
	    cin>>n;
	    n*=3;
	    vector<int> v(n);
	    for(int i=0;i<n;i++) cin >> v[i];
	    sort(v.begin(),v.end(),greater<int>());
	    
	    vector<int> psum(n+1, 0);
	    psum[1] = v[0];
	    for(int i=2; i<=n; i++){
	        psum[i] = psum[i-1] + v[i-1];
	    }
	    
	    
	    n/=3;
	    int ans = 0;
	    for(int a = 0; a <= n; a++){
	        int tot = n - a;
	        int low = 0;
	        int high = tot;
	        while (low < high){
	            int b = (low+high)/2;
	            int c = (tot - b);
	            
	            int cur = 4*(psum[a+2*b]-psum[a]) + 3*(psum[a+2*b+3*c]-psum[a+2*b]);
	            
	            b++;
	            c--;
	            int cur2 = 4*(psum[a+2*b]-psum[a]) + 3*(psum[a+2*b+3*c]-psum[a+2*b]);
	            
	            b--;
	            if (cur < cur2){
	                low = b+1;
	            }
	            else{
	                high = b;
	            }
	        }
	        
	        int b = low;
	        int c = n-a-b;
	        
	        ans = max(ans, 6*psum[a] + 4*(psum[a+2*b]-psum[a]) + 3*(psum[a+2*b+3*c]-psum[a+2*b]));
	    }
	    cout << ans << endl;
	}
}
